/// <summary>
/// Base class for PricingAttribute table <c>SalesLine</c>
/// </summary>
internal abstract class GUPPricingAttributeSalesLine extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    protected SalesLine getTableRecord(Common _pricingObject)
    {
        SalesLine  salesLine = _pricingObject as SalesLine;

        return salesLine;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(SalesLine)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(SalesLine));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(SalesLine));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(SalesLine), qbdsRoot);
            }
        }

        return qbdsRoot;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
